<!doctype html>
<html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?= html_escape($product['name']) ?> — Rembang UMKM</title><link rel="icon" href="<?= base_url('assets/favicon.ico?v=1') ?>"><link rel="stylesheet" href="<?= base_url('assets/tabler.min.css') ?>"><link rel="stylesheet" href="<?= base_url('assets/marketplace.css?v=5') ?>"></head>
<body class="shop-body"><?php $this->load->view('market/_header'); ?>
<main class="shop-main container-xl"><nav class="shop-breadcrumb"><a href="<?= site_url('jelajah') ?>">Beranda</a><span>›</span><a href="<?= site_url('toko/'.$product['store_slug']) ?>"><?= html_escape($product['store_name']) ?></a><span>›</span><strong><?= html_escape($product['name']) ?></strong></nav>
<div class="shop-product-detail"><div class="shop-gallery"><div class="shop-detail-image <?= $media ? 'has-photo' : '' ?>" id="product-main-media"><?php if ($media): ?><?php $first=$media[0]; if ($first['media_type']==='image'): ?><img src="<?= base_url('assets/products/'.rawurlencode($first['storage_key'])) ?>" alt="<?= html_escape($first['alt_text'] ?: $product['name']) ?>"><?php else: ?><video controls playsinline preload="metadata" src="<?= base_url('assets/products/'.rawurlencode($first['storage_key'])) ?>"></video><?php endif; ?><?php else: ?><img src="<?= category_art_url($product['category_slug'] ?: 'kuliner') ?>" alt=""><?php endif; ?></div>
<?php if ($media): ?><div class="shop-gallery-thumbs"><?php foreach ($media as $item): ?><button type="button" class="shop-gallery-thumb" data-type="<?= $item['media_type'] ?>" data-src="<?= html_escape(base_url('assets/products/'.rawurlencode($item['storage_key']))) ?>" data-alt="<?= html_escape($item['alt_text'] ?: $product['name']) ?>"><?php if ($item['media_type']==='image'): ?><img src="<?= base_url('assets/products/'.rawurlencode($item['storage_key'])) ?>" alt=""><?php else: ?><span>▶ Video</span><?php endif; ?></button><?php endforeach; ?></div><?php endif; ?></div>
<div class="shop-detail-copy"><span class="shop-eyebrow">PRODUK LOKAL</span><h1><?= html_escape($product['name']) ?></h1><div class="shop-detail-price"><?= $product['price_min'] !== NULL ? 'Rp'.number_format((float)$product['price_min'],0,',','.') : 'Tanyakan harga' ?><?php if ($product['price_max'] !== NULL && $product['price_max'] != $product['price_min']): ?> – Rp<?= number_format((float)$product['price_max'],0,',','.') ?><?php endif; ?><small><?= html_escape($product['unit_label'] ? 'per '.$product['unit_label'] : '') ?></small></div>
<form class="shop-buy-form" method="post"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>">
<?php if ($variants): ?><fieldset class="shop-variant-field"><legend>Pilih variasi</legend><div class="shop-variant-list"><?php foreach ($variants as $variant): ?><label class="shop-variant-option"><input type="radio" name="variant_id" value="<?= (int)$variant['id'] ?>" required <?= $variant['stock_qty'] !== NULL && (int)$variant['stock_qty']===0 ? 'disabled' : '' ?>><span><?= html_escape($variant['label']) ?><?php if ($variant['price'] !== NULL): ?><small>Rp<?= number_format((float)$variant['price'],0,',','.') ?></small><?php endif; ?><?php if ($variant['stock_qty'] !== NULL): ?><small><?= (int)$variant['stock_qty'] ?> tersedia</small><?php endif; ?></span></label><?php endforeach; ?></div></fieldset><?php endif; ?>
<label class="shop-buy-quantity">Jumlah <input type="number" name="quantity" min="1" max="99" value="1" required inputmode="numeric"></label><div class="shop-detail-actions"><button class="shop-outline-button" type="submit" formaction="<?= site_url('keranjang/tambah') ?>">+ Keranjang</button><button class="shop-primary-button" type="submit" formaction="<?= site_url('kontak/produk') ?>">Tanya produk <span aria-hidden="true">↗</span></button></div></form>
<p class="shop-detail-note">Harga akhir dan ketersediaan dikonfirmasi langsung dengan penjual.</p><a class="shop-detail-store" href="<?= site_url('toko/'.$product['store_slug']) ?>"><span>◈</span><span><strong><?= html_escape($product['store_name']) ?></strong><small>⌖ <?= html_escape($product['district_name'] ?: 'Rembang') ?></small></span><span aria-hidden="true">→</span></a></div></div>
<section class="shop-product-description"><h2>Deskripsi produk</h2><p><?= nl2br(html_escape($product['description'] ?: 'Informasi produk tersedia dari penjual.')) ?></p><?php if ($product['availability_note']): ?><p><?= html_escape($product['availability_note']) ?></p><?php endif; ?><?php if ($specs): ?><h2>Spesifikasi</h2><dl><?php foreach ($specs as $spec): ?><div><dt><?= html_escape($spec['spec_name']) ?></dt><dd><?= html_escape($spec['spec_value']) ?></dd></div><?php endforeach; ?></dl><?php endif; ?></section></main>
<?php $active_tab='home';$this->load->view('market/_bottom_nav', array('active_tab' => $active_tab, 'cart_count' => $cart_count)); ?><script>document.querySelectorAll('.shop-gallery-thumb').forEach(function(button){button.addEventListener('click',function(){var wrap=document.getElementById('product-main-media');wrap.replaceChildren();var node=document.createElement(button.dataset.type==='video'?'video':'img');node.src=button.dataset.src;if(button.dataset.type==='video'){node.controls=true;node.playsInline=true;}else{node.alt=button.dataset.alt;}wrap.appendChild(node);});});</script></body></html>
